-- Synthetic data: find complaints whose lot is missing or unknown in MES
CREATE TABLE complaint (id TEXT, product_code TEXT, lot TEXT, received DATE, reportable TEXT, reason TEXT);
CREATE TABLE mes_lot (lot TEXT, product_code TEXT);
INSERT INTO complaint VALUES
 ('C-101','PUMP-A','L2301','2026-03-02','No','No injury, alarm worked'),
 ('C-102','PUMP-A','','2026-03-03','No',''),
 ('C-103','PUMP-B','L9999','2026-03-05','Yes','Over-infusion reported');
INSERT INTO mes_lot VALUES ('L2301','PUMP-A'), ('L2302','PUMP-B');

SELECT c.id,
  CASE WHEN c.lot = '' THEN 'lot missing'
       WHEN m.lot IS NULL THEN 'lot not in MES'
       WHEN m.product_code <> c.product_code THEN 'product mismatch'
  END AS lot_issue,
  CASE WHEN c.reason = '' THEN 'no reportability reason' END AS reason_issue
FROM complaint c LEFT JOIN mes_lot m ON m.lot = c.lot
WHERE c.lot = '' OR m.lot IS NULL OR m.product_code <> c.product_code OR c.reason = '';
